process:
updater = get_plugin('LlmLinkBulkUpdater')
target = (state.get('target_model') or state.get('model') or '').strip()
source = (state.get('source_model') or '').strip() or None
raw_dry = state.get('dry_run', False)
if isinstance(raw_dry, str):
    dry_run = raw_dry.strip().lower() in ('1', 'true', 'yes', 'y', 'on')
else:
    dry_run = bool(raw_dry)
agent_ids = state.get('agent_ids')
change_note = (state.get('change_note') or '').strip()
if not updater:
    __result__ = {'error': 'LlmLinkBulkUpdater plugin unavailable', 'updated': [], 'skipped': []}
elif not target:
    __result__ = {'error': "Missing 'target_model' (LLM connector id under meta/llms/)", 'updated': [], 'skipped': []}
else:
    __result__ = updater.apply(
        target,
        source_model=source,
        agent_ids=agent_ids,
        dry_run=dry_run,
        change_note=change_note,
    )
